import React, { useState, useEffect } from 'react';
import { 
  Container, Row, Col, Card, 
  Alert, Badge, Table, Button, Spinner 
} from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useNotification } from '../contexts/NotificationContext';

const DashboardPage = () => {
  const navigate = useNavigate();
  const { user, logout } = useAuth();
  const { showNotification, showInfo, showError } = useNotification();
  
  const [loading, setLoading] = useState(true);
  const [dashboardData, setDashboardData] = useState({
    stats: {
      totalSearches: 0,
      vendorsTracked: 0,
      packagesFound: 0,
      exportCount: 0
    },
    recentSearches: [],
    topVendors: [],
    favoriteLPSE: 'Kementerian PU'
  });

  useEffect(() => {
    loadDashboard();
  }, []);

  const loadDashboard = async () => {
    setLoading(true);
    try {
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      // Mock data
      const mockData = {
        stats: {
          totalSearches: 12,
          vendorsTracked: 5,
          packagesFound: 8,
          exportCount: 3
        },
        recentSearches: [
          { id: 1, type: 'vendor', query: 'Adhi Karya', date: '2024-01-15', results: 5 },
          { id: 2, type: 'package', query: 'jalan', date: '2024-01-14', results: 12 },
          { id: 3, type: 'vendor', query: 'Waskita', date: '2024-01-13', results: 3 },
          { id: 4, type: 'package', query: 'gedung', date: '2024-01-12', results: 7 }
        ],
        topVendors: [
          { name: 'PT Adhi Karya', tenderCount: 8, totalValue: 'Rp 5.2 T' },
          { name: 'PT Waskita Karya', tenderCount: 6, totalValue: 'Rp 4.8 T' },
          { name: 'PT Wijaya Karya', tenderCount: 5, totalValue: 'Rp 3.9 T' },
          { name: 'PT PP (Persero)', tenderCount: 4, totalValue: 'Rp 3.2 T' }
        ]
      };
      
      setDashboardData(mockData);
      showInfo('Dashboard loaded successfully');
    } catch (error) {
      console.error('Error loading dashboard:', error);
      showError('Gagal memuat dashboard');
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    logout();
    showNotification('Logout berhasil', 'success');
    navigate('/');
  };

  const handleRefresh = () => {
    loadDashboard();
  };

  const handleExportData = () => {
    showNotification('Fitur export data dashboard akan segera hadir!', 'info');
  };

  if (loading) {
    return (
      <Container className="py-5">
        <Row className="justify-content-center">
          <Col md={6} className="text-center">
            <Spinner animation="border" variant="primary" />
            <p className="mt-3">Memuat dashboard...</p>
          </Col>
        </Row>
      </Container>
    );
  }

  return (
    <Container className="py-4">
      {/* Header */}
      <Row className="mb-4">
        <Col>
          <div className="d-flex justify-content-between align-items-center">
            <div>
              <h1 className="display-6 fw-bold">
                <i className="fas fa-tachometer-alt me-2"></i>
                Dashboard
              </h1>
              <p className="text-muted mb-0">
                Selamat datang, <strong>{user?.name}</strong>!
              </p>
            </div>
            <div>
              <Button 
                variant="outline-primary" 
                size="sm" 
                className="me-2"
                onClick={handleRefresh}
              >
                <i className="fas fa-sync-alt me-1"></i>
                Refresh
              </Button>
              <Button 
                variant="outline-danger" 
                size="sm"
                onClick={handleLogout}
              >
                <i className="fas fa-sign-out-alt me-1"></i>
                Logout
              </Button>
            </div>
          </div>
        </Col>
      </Row>

      {/* Stats Cards */}
      <Row className="mb-4">
        <Col md={3} className="mb-3">
          <Card className="shadow-sm border-primary">
            <Card.Body>
              <div className="d-flex justify-content-between align-items-center">
                <div>
                  <h6 className="text-muted mb-2">Total Pencarian</h6>
                  <h3 className="mb-0">{dashboardData.stats.totalSearches}</h3>
                </div>
                <div className="bg-primary bg-opacity-10 p-3 rounded">
                  <i className="fas fa-search fa-2x text-primary"></i>
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>
        
        <Col md={3} className="mb-3">
          <Card className="shadow-sm border-success">
            <Card.Body>
              <div className="d-flex justify-content-between align-items-center">
                <div>
                  <h6 className="text-muted mb-2">Vendor Tracked</h6>
                  <h3 className="mb-0">{dashboardData.stats.vendorsTracked}</h3>
                </div>
                <div className="bg-success bg-opacity-10 p-3 rounded">
                  <i className="fas fa-building fa-2x text-success"></i>
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>
        
        <Col md={3} className="mb-3">
          <Card className="shadow-sm border-info">
            <Card.Body>
              <div className="d-flex justify-content-between align-items-center">
                <div>
                  <h6 className="text-muted mb-2">Paket Ditemukan</h6>
                  <h3 className="mb-0">{dashboardData.stats.packagesFound}</h3>
                </div>
                <div className="bg-info bg-opacity-10 p-3 rounded">
                  <i className="fas fa-box fa-2x text-info"></i>
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>
        
        <Col md={3} className="mb-3">
          <Card className="shadow-sm border-warning">
            <Card.Body>
              <div className="d-flex justify-content-between align-items-center">
                <div>
                  <h6 className="text-muted mb-2">Export Data</h6>
                  <h3 className="mb-0">{dashboardData.stats.exportCount}</h3>
                </div>
                <div className="bg-warning bg-opacity-10 p-3 rounded">
                  <i className="fas fa-download fa-2x text-warning"></i>
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Recent Searches */}
      <Row className="mb-4">
        <Col lg={6}>
          <Card className="shadow-sm h-100">
            <Card.Header className="bg-light">
              <h6 className="mb-0">
                <i className="fas fa-history me-2"></i>
                Pencarian Terakhir
              </h6>
            </Card.Header>
            <Card.Body className="p-0">
              <Table hover className="mb-0">
                <thead className="table-light">
                  <tr>
                    <th>Type</th>
                    <th>Query</th>
                    <th>Date</th>
                    <th>Results</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {dashboardData.recentSearches.map((search) => (
                    <tr key={search.id}>
                      <td>
                        <Badge bg={search.type === 'vendor' ? 'primary' : 'success'}>
                          {search.type}
                        </Badge>
                      </td>
                      <td>{search.query}</td>
                      <td>{search.date}</td>
                      <td>
                        <Badge bg="info">{search.results}</Badge>
                      </td>
                      <td>
                        <Button
                          size="sm"
                          variant="outline-primary"
                          onClick={() => {
                            if (search.type === 'vendor') {
                              navigate(`/vendor?q=${encodeURIComponent(search.query)}`);
                            } else {
                              navigate(`/package?q=${encodeURIComponent(search.query)}`);
                            }
                          }}
                        >
                          <i className="fas fa-redo"></i>
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>

        {/* Top Vendors */}
        <Col lg={6}>
          <Card className="shadow-sm h-100">
            <Card.Header className="bg-light">
              <h6 className="mb-0">
                <i className="fas fa-trophy me-2 text-warning"></i>
                Top Vendors
              </h6>
            </Card.Header>
            <Card.Body className="p-0">
              <Table hover className="mb-0">
                <thead className="table-light">
                  <tr>
                    <th>Vendor Name</th>
                    <th>Tender Count</th>
                    <th>Total Value</th>
                    <th>Action</th>
                  </tr>
                </thead>
                <tbody>
                  {dashboardData.topVendors.map((vendor, index) => (
                    <tr key={index}>
                      <td>
                        <strong>{vendor.name}</strong>
                      </td>
                      <td>
                        <Badge bg="primary">{vendor.tenderCount}</Badge>
                      </td>
                      <td>
                        <Badge bg="success">{vendor.totalValue}</Badge>
                      </td>
                      <td>
                        <Button
                          size="sm"
                          variant="outline-success"
                          onClick={() => navigate(`/vendor?q=${encodeURIComponent(vendor.name)}`)}
                        >
                          <i className="fas fa-search"></i>
                        </Button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Quick Actions */}
      <Row className="mb-4">
        <Col>
          <Card className="shadow-sm">
            <Card.Header className="bg-light">
              <h6 className="mb-0">
                <i className="fas fa-bolt me-2"></i>
                Quick Actions
              </h6>
            </Card.Header>
            <Card.Body>
              <div className="d-flex flex-wrap gap-3">
                <Button 
                  variant="primary"
                  onClick={() => navigate('/vendor')}
                >
                  <i className="fas fa-search me-2"></i>
                  Cari Vendor
                </Button>
                <Button 
                  variant="success"
                  onClick={() => navigate('/package')}
                >
                  <i className="fas fa-box me-2"></i>
                  Cari Paket
                </Button>
                <Button 
                  variant="info"
                  onClick={() => navigate('/sbu')}
                >
                  <i className="fas fa-certificate me-2"></i>
                  Cari SBU
                </Button>
                <Button 
                  variant="warning"
                  onClick={handleExportData}
                >
                  <i className="fas fa-download me-2"></i>
                  Export Data
                </Button>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* User Info */}
      <Row>
        <Col>
          <Card className="shadow-sm">
            <Card.Header className="bg-light">
              <h6 className="mb-0">
                <i className="fas fa-user me-2"></i>
                Informasi Akun
              </h6>
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md={4}>
                  <div className="mb-3">
                    <small className="text-muted">Nama</small>
                    <p className="mb-0 fw-bold">{user?.name || 'N/A'}</p>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="mb-3">
                    <small className="text-muted">Email</small>
                    <p className="mb-0 fw-bold">{user?.email || 'N/A'}</p>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="mb-3">
                    <small className="text-muted">Terdaftar Sejak</small>
                    <p className="mb-0 fw-bold">
                      {user?.created_at ? new Date(user.created_at).toLocaleDateString('id-ID') : 'N/A'}
                    </p>
                  </div>
                </Col>
              </Row>
              
              <Alert variant="info" className="mt-3">
                <h6>
                  <i className="fas fa-info-circle me-2"></i>
                  Fitur Premium Akan Datang
                </h6>
                <ul className="mb-0">
                  <li>Advanced analytics dengan chart</li>
                  <li>Export data ke Excel (XLSX)</li>
                  <li>Notifikasi real-time tender baru</li>
                  <li>API access untuk integrasi</li>
                </ul>
              </Alert>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default DashboardPage;